ALTER proc [dbo].[SIM_TeachingTimeResearch_Add]
(
	@TeacherID nvarchar(200),
	@YearID int,
	@Semester int,
	@TeachHour decimal(18,2) = null,
	@ResearchHour decimal(18,2) = null,
	@SavePrev decimal(18,2) = null,
	@ResearchNow decimal(18,2) = null,
	@ResearchContent nvarchar(max) = null,
	@DecisionNo nvarchar(500) = null,
	@CreatedUser nvarchar(50) = null
)
AS
Begin

	Declare @decTotalHour decimal(18,2)
	Declare @decSaveNext decimal(18,2)
	Declare @decLackHour decimal(18,2)

	Set @decTotalHour = isnull(@SavePrev, 0) + isnull(@ResearchNow, 0)

	If @decTotalHour >= isnull(@ResearchHour, 0)
	Begin
		Set @decSaveNext = @decTotalHour - isnull(@ResearchHour, 0)
		Set @decLackHour = 0
	End
	Else
	Begin
		Set @decSaveNext = 0
		Set @decLackHour = isnull(@ResearchHour, 0) - @decTotalHour
	End

	If Exists
	(
		Select 1
		From SIM_TeachingTimeResearch
		Where TeacherID = @TeacherID
			and YearID = @YearID
			and Semester = @Semester
	)
	Begin
		Raiserror(N'Giảng viên đã có dữ liệu giờ NCKH trong năm học và học kỳ này.', 16, 1)
		Return
	End

	Insert Into SIM_TeachingTimeResearch
	(
		TeacherID,
		YearID,
		Semester,
		TeachHour,
		ResearchHour,
		SavePrev,
		ResearchNow,
		ResearchContent,
		DecisionNo,
		TotalHour,
		SaveNext,
		LackHour,
		CreatedUser
	)
	Values
	(
		@TeacherID,
		@YearID,
		@Semester,
		@TeachHour,
		@ResearchHour,
		@SavePrev,
		@ResearchNow,
		@ResearchContent,
		@DecisionNo,
		@decTotalHour,
		@decSaveNext,
		@decLackHour,
		@CreatedUser
	)

	Select Convert(bigint, SCOPE_IDENTITY())

End

