			Set @decSaveNext = @decTotalHour - isnull(@ResearchHour, 0)
			Set @decLackHour = 0
		End
		Else
		Begin
			Set @decSaveNext = 0
			Set @decLackHour = isnull(@ResearchHour, 0) - @decTotalHour
		End
	End
	Else
	Begin
		Set @decSaveNext = @SaveNext
		Set @decLackHour = @LackHour
	End

	If Exists
	(
		Select 1
		From SIM_TeachingTimeResearch
		Where TeacherID = @TeacherID
			and YearID = @YearID
			and Semester = @Semester
	)
	Begin
		Raiserror(N'Giảng viên đã có dữ liệu giờ NCKH trong năm học và học kỳ này.', 16, 1)
		Return
	End

	Insert Into SIM_TeachingTimeResearch
	(
		TeacherID,
		YearID,
		Semester,
		TeachHour,
		ResearchHour,
		SavePrev,
		ResearchNow,
		ResearchContent,
		DecisionNo,
		TotalHour,
		SaveNext,
		LackHour,
		CreatedUser
	)
	Values
	(
		@TeacherID,
		@YearID,
		@Semester,
		@TeachHour,
		@ResearchHour,
		@SavePrev,
		@ResearchNow,
		@ResearchContent,
		@DecisionNo,
		@decTotalHour,
		@decSaveNext,
		@decLackHour,
		@CreatedUser
	)

	Select Convert(bigint, SCOPE_IDENTITY())

End

